<template>
  <div class="page-container">
    <el-card shadow="never">
      <div slot="header" style="font-size: 18px; font-weight: 600;">{{ isEdit ? '编辑报修' : '新建报修' }}</div>
      <el-form ref="form" :model="form" :rules="rules" label-width="100px" style="max-width: 800px;">
        <el-form-item label="报修标题" prop="title">
          <el-input v-model="form.title" placeholder="请输入报修标题" />
        </el-form-item>
        <el-form-item label="报修位置" prop="location">
          <el-input v-model="form.location" placeholder="请输入详细位置，如：教学楼A 301教室" />
        </el-form-item>
        <el-row :gutter="20">
          <el-col :span="8">
            <el-form-item label="楼栋" prop="building">
              <el-input v-model="form.building" placeholder="如：教学楼A" />
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="楼层">
              <el-input v-model="form.floor" placeholder="如：3层" />
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="房间号">
              <el-input v-model="form.room" placeholder="如：301" />
            </el-form-item>
          </el-col>
        </el-row>
        <el-form-item label="报修分类" prop="category">
          <el-select v-model="form.category" placeholder="请选择" style="width:100%">
            <el-option label="电气" value="electrical" />
            <el-option label="水暖" value="plumbing" />
            <el-option label="家具" value="furniture" />
            <el-option label="门窗" value="door_window" />
            <el-option label="地面" value="floor" />
            <el-option label="墙面" value="wall" />
            <el-option label="其他" value="other" />
          </el-select>
        </el-form-item>
        <el-form-item label="优先级" prop="priority">
          <el-radio-group v-model="form.priority">
            <el-radio-button label="low">低</el-radio-button>
            <el-radio-button label="medium">中</el-radio-button>
            <el-radio-button label="high">高</el-radio-button>
            <el-radio-button label="urgent">紧急</el-radio-button>
          </el-radio-group>
        </el-form-item>
        <el-form-item label="问题描述">
          <el-input v-model="form.description" type="textarea" :rows="4" placeholder="请详细描述问题..." />
        </el-form-item>

        <el-divider content-position="left">BIM模型关联</el-divider>

        <el-row :gutter="20">
          <el-col :span="10">
            <el-form-item label="构件名称">
              <el-input v-model="form.model_element_name" placeholder="点击BIM模型选择构件或手动输入" readonly>
                <el-button slot="append" @click="$router.push('/bim')">选择构件</el-button>
              </el-input>
            </el-form-item>
          </el-col>
          <el-col :span="6">
            <el-form-item label="构件ID">
              <el-input v-model="form.model_element_id" placeholder="构件ID" />
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="所属模型">
              <el-input v-model="form.model_name" placeholder="所属模型" readonly />
            </el-form-item>
          </el-col>
        </el-row>

        <el-form-item>
          <el-button type="primary" :loading="submitting" @click="handleSubmit">{{ isEdit ? '更新' : '提交报修' }}</el-button>
          <el-button @click="$router.back()">取消</el-button>
        </el-form-item>
      </el-form>
    </el-card>
  </div>
</template>

<script>
import { maintenanceApi } from '../../api'

export default {
  name: 'MaintenanceFormView',
  data() {
    return {
      submitting: false,
      // 报修表单数据
      // 从 BIM 页面跳转时，以下字段会通过 query 参数自动填充：
      // model_element_id、model_element_name、floor、room、model_name
      form: {
        title: '', description: '', location: '', building: '', floor: '', room: '',
        category: 'other', priority: 'medium',
        model_element_id: '', model_element_name: '', model_name: ''
      },
      // 表单验证规则
      rules: {
        title: [{ required: true, message: '请输入报修标题', trigger: 'blur' }],
        location: [{ required: true, message: '请输入报修位置', trigger: 'blur' }],
        category: [{ required: true, message: '请选择分类', trigger: 'change' }]
      }
    }
  },
  computed: {
    isEdit() {
      return !!this.$route.params.id
    }
  },
  mounted() {
    // 从 BIM 页面跳转过来时，读取 query 参数自动填充表单
    if (this.$route.query.elementId) {
      this.form.model_element_id = this.$route.query.elementId
      this.form.model_element_name = this.$route.query.elementName
      this.form.floor = this.$route.query.floor || ''
      this.form.room = this.$route.query.room || ''
      this.form.model_name = this.$route.query.modelName || ''
    }
    // 编辑模式下加载已有数据
    if (this.isEdit) {
      this.fetchDetail()
    }
  },
  methods: {
    async fetchDetail() {
      const res = await maintenanceApi.getDetail(this.$route.params.id)
      if (res.code === 200) {
        Object.assign(this.form, {
          title: res.data.title,
          description: res.data.description,
          location: res.data.location,
          building: res.data.building,
          floor: res.data.floor,
          room: res.data.room,
          category: res.data.category,
          priority: res.data.priority,
          model_element_id: res.data.model_element_id || '',
          model_element_name: res.data.model_element_name || '',
          model_name: res.data.model_name || ''
        })
      }
    },
    handleSubmit() {
      this.$refs.form.validate(async (valid) => {
        if (!valid) return
        this.submitting = true
        try {
          const res = this.isEdit
            ? await maintenanceApi.update(this.$route.params.id, this.form)
            : await maintenanceApi.create(this.form)
          if (res.code === 200) {
            this.$message.success(this.isEdit ? '更新成功' : '报修成功')
            this.$router.push('/maintenance')
          } else {
            this.$message.error(res.message)
          }
        } catch (e) {
          this.$message.error('操作失败')
        } finally {
          this.submitting = false
        }
      })
    }
  }
}
</script>
